arguments.command:
cat > /tmp/describe_alt.mjs << 'EOF'
import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const apiKey = process.env.GEMINI_API_KEY;
if (!apiKey) {
  console.error("錯誤：需要設定 GEMINI_API_KEY");
  process.exit(1);
}

const imagePath = process.argv[2];
if (!imagePath) {
  console.error("用法：node describe_alt.mjs <image-path>");
  process.exit(1);
}

const imageData = await readFile(imagePath);
const base64 = imageData.toString("base64");
const mimeType = "image/jpeg";

const prompt = `請仔細觀察這張圖片，並以繁體中文（zh-TW）Markdown 格式提供以下資訊：

## 圖片描述
描述圖片的整體場景和內容，包括環境、氛圍與主要活動。

## 文字辨識（OCR）
列出圖片中出現的所有可辨識文字。若無文字，請說明「圖片中未發現文字」。

## 關鍵物件
以條列方式列出畫面中的關鍵物件或元素。

請確保輸出完整且結構清楚。`;

const response = await fetch(
  `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${apiKey}`,
  {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      contents: [{
        parts: [
          { text: prompt },
          { inline_data: { mime_type: mimeType, data: base64 } }
        ]
      }]
    })
  }
);

const json = await response.json();
if (!response.ok) {
  console.error("API Error:", JSON.stringify(json, null, 2));
  process.exit(1);
}

const text = json.candidates?.[0]?.content?.parts?.[0]?.text;
console.log(text);
EOF
echo "script created"

